const COUNTRY_OUTLINE_SLUGS=new Set(Object.keys(COUNTRY_OUTLINE_DATA));
function countryOutlineMarkup(country=''){
  const slug=slugifyCountry(country);
  const shape=COUNTRY_OUTLINE_DATA[slug];
  if(!shape)return '';
  const paths=shape.p.map(d=>`<path d="${esc(d)}"></path>`).join('');
  return `<svg class="home-hero-country-outline" viewBox="${esc(shape.v)}" preserveAspectRatio="xMidYMid meet" aria-hidden="true">${paths}</svg>`;
}
const COUNTRY_CURRENCY_CODES={
  'algeria':'DZD','australia':'AUD','austria':'EUR','belgium':'EUR','bosnia-and-herzegovina':'BAM','bulgaria':'EUR','canada':'CAD',
  'croatia':'EUR','cyprus':'EUR','czech-republic':'CZK','denmark':'DKK','egypt':'EGP','finland':'EUR','france':'EUR','germany':'EUR',
  'greece':'EUR','hungary':'HUF','iceland':'ISK','indonesia':'IDR','ireland':'EUR','italy':'EUR','japan':'JPY','jordan':'JOD',
  'liechtenstein':'CHF','luxembourg':'EUR','malta':'EUR','mexico':'MXN','monaco':'EUR','montenegro':'EUR','morocco':'MAD',
  'netherlands':'EUR','new-zealand':'NZD','north-macedonia':'MKD','norway':'NOK','poland':'PLN','portugal':'EUR','romania':'RON',
  'russia':'RUB','serbia':'RSD','singapore':'SGD','slovakia':'EUR','slovenia':'EUR','spain':'EUR','sweden':'SEK','switzerland':'CHF',
  'thailand':'THB','turkey':'TRY','united-arab-emirates':'AED','united-kingdom':'GBP','united-states':'USD','vietnam':'VND'
};
function countryCurrencyCode(country='',fallback='AUD'){
  return COUNTRY_CURRENCY_CODES[slugifyCountry(country)]||currencyCode(fallback,'AUD');
}
function countryCurrencyDetails(country='',fallback='AUD'){
  return currencyDetails(countryCurrencyCode(country,fallback));
}
const clone = value => JSON.parse(JSON.stringify(value));
const esc = value => String(value ?? '').replace(/[&<>'"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const money = value => new Intl.NumberFormat('en-AU', {style:'currency', currency:'AUD', maximumFractionDigits:0}).format(Number(value || 0));
const moneyExact = value => new Intl.NumberFormat('en-AU', {style:'currency', currency:'AUD', minimumFractionDigits:2, maximumFractionDigits:4}).format(Number(value || 0));
const moneyCents = value => new Intl.NumberFormat('en-AU', {style:'currency', currency:'AUD', minimumFractionDigits:2, maximumFractionDigits:2}).format(Number(value || 0));
const localMoney = (value, symbol='') => `${esc(symbol)}${Number(value || 0).toLocaleString('en-AU', {maximumFractionDigits:2})}`;
const localNumber = value => Number(value || 0).toLocaleString('en-AU', {maximumFractionDigits:2});
function budgetCurrencyFigure(value,currency='AUD',symbol='',tone=''){
  const code=currencyCode(currency,'AUD'),details=currencyDetails(code),mark=currencySymbol(symbol||details.symbol,'');
  const amount=localNumber(value),length=amount.length;
  const fit=length>=18?'budget-amount-xxl':length>=15?'budget-amount-xl':length>=12?'budget-amount-lg':length>=9?'budget-amount-md':'budget-amount-normal';
  return `<div class="budget-currency-id"><strong>${esc(code)}</strong>${mark?`<em>${esc(mark)}</em>`:''}</div><b class="budget-local-figure ${esc(tone)} ${fit}">${esc(amount)}</b>`;
}
const parseDate = value => value ? new Date(`${value}T12:00:00`) : null;
function journeyHorizonEndDate(){
  const start=parseDate(state?.settings?.journeyStart)||parseDate('2026-01-14');
  return `${start.getFullYear()+MAX_JOURNEY_YEARS-1}-12-31`;
}
function journeyDateWithinHorizon(value){return validISODate(value)&&String(value)<=journeyHorizonEndDate();}
const dateFmt = value => { if(!value) return '—'; const d=parseDate(value); return `${String(d.getDate()).padStart(2,'0')}/${String(d.getMonth()+1).padStart(2,'0')}/${d.getFullYear()}`; };
const days = (start, end) => start && end ? Math.max(1, Math.round((parseDate(end)-parseDate(start))/86400000)+1) : 0;
const calendarDayDelta = (start, end) => start && end ? Math.round((parseDate(end)-parseDate(start))/86400000) : 0;
const dateOffsetFrom = (date, offset=0) => { const value=parseDate(date)||parseDate(itineraryReferenceDate?.()||'2026-01-14')||parseDate('2026-01-14');value.setDate(value.getDate()+Number(offset||0));return value; };
const remainingDaysAfterToday = end => validISODate(end) ? Math.max(0, calendarDayDelta(itineraryReferenceDate(),end)) : 0;
const remainingDaysIncludingToday = end => {
  if(!validISODate(end)) return 0;
  const delta=calendarDayDelta(itineraryReferenceDate(),end);
  return delta<0?0:delta+1;
};
const elapsedDaysInRange = (start,end,reference=itineraryReferenceDate()) => {
  if(!validISODate(start)||!validISODate(end)||!validISODate(reference)||end<start||reference<start) return 0;
  return days(start,reference>end?end:reference);
};
const dayCountLabel = count => `${count} day${Number(count)===1?'':'s'}`;
const between = (date, start, end) => date && start && end && date >= start && date <= end;

