function iconMarkup(name, extra=''){
  const key=name==='reservations'?'flight':name==='accommodation'?'hotel':name==='attraction'?'tickets':name;
  const prestigeAssets={flight:'prestige-flight.png',train:'prestige-train.png',cruise:'prestige-cruise.png',hotel:'prestige-stay.png',budget:'prestige-budget.png',calendar:'prestige-calendar.png',itinerary:'prestige-itinerary.png',checklist:'prestige-checklist.png',vault:'prestige-vault.png'};
  if(prestigeAssets[key]) return `<span class="ui-icon prestige-soft-glass prestige-${key} ${extra}" aria-hidden="true"><img src="${prestigeAssets[key]}" alt=""></span>`;
  return `<span class="ui-icon prestige-soft-glass vector-prestige prestige-${key} ${extra}" aria-hidden="true">${iconSvg(key)}</span>`;
}
function navIcon(name){
  const rasterMap={home:'home',budget:'budget',reservations:'flight',itinerary:'itinerary',calendar:'calendar',journeys:'journeys',checklist:'checklist',vault:'vault',settings:'settings'};
  return iconMarkup(rasterMap[name]||name,'nav-mark');
}
function namedTextIcon(name, text, extra=''){ return `<span class="icon-text ${extra}">${iconMarkup(name,'text-glyph')}${esc(text)}</span>`; }
function bankKey(name=''){
  const value=String(name||'').trim().toLowerCase();
  if(value.includes('commonwealth')) return 'commonwealth';
  if(value==='nab') return 'nab';
  if(value==='anz') return 'anz';
  if(value.includes('westpac')) return 'westpac';
  if(value.includes('me')) return 'me';
  if(value.includes('wise')) return 'wise';
  return value.replace(/[^a-z]+/g,'-')||'account';
}
function bankIcon(name=''){
  const key=bankKey(name), asset={commonwealth:'bank-commonwealth',nab:'bank-nab',anz:'bank-anz',westpac:'bank-westpac',me:'bank-me',wise:'bank-wise'}[key];
  if(asset) return `<span class="brand-mark approved-bank-mark" aria-hidden="true"><img src="ui-icon-${asset}.png" alt=""></span>`;
  return `<span class="brand-mark bank-generic" aria-hidden="true"><b>${esc(String(name||'').slice(0,2).toUpperCase())}</b></span>`;
}
function accountLabel(name=''){
  const label=String(name||'').trim()||'Account';
  const normalized=label==='Commonwealth'?'Commonwealth Bank':label;
  return `<span class="account-label">${bankIcon(label)}<span>${esc(normalized)}</span></span>`;
}
function expenseCategoryIcon(category=''){
  const value=String(category||'').toLowerCase();
  if(value.includes('grocer')) return 'groceries';
  if(value.includes('eat')||value.includes('food')) return 'food';
  if(value.includes('transport')) return 'transport';
  if(value.includes('entertain')) return 'entertainment';
  if(value.includes('shop')) return 'shopping';
  return 'miscellaneous';
}
function reservationIconName(type=''){
  const value=String(type||'').toLowerCase();
  if(value.includes('flight')) return 'flight';
  if(value.includes('train')) return 'train';
  if(value.includes('cruise')) return 'cruise';
  if(value.includes('rv')||value.includes('motorhome')) return 'motorhome';
  if(value.includes('accommodation')||value.includes('hotel')||value.includes('airbnb')) return 'hotel';
  if(value.includes('ticket')||value.includes('attraction')) return 'tickets';
  return 'reservations';
}

