function loadState(){
  try {
    let raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) {
      for (const key of LEGACY_STORAGE_KEYS) { raw = localStorage.getItem(key); if (raw) break; }
    }
    return hydrate(raw ? JSON.parse(raw) : demoReviewState());
  } catch (error) {
    console.error('Travel Command Centre data recovery:',error);
    return hydrate(null);
  }
}
function sortedItinerary(){ return [...state.itinerary].map(x=>normalizeItineraryEntry(x)).sort((a,b)=>String(a.arrival).localeCompare(String(b.arrival))||String(a.departure).localeCompare(String(b.departure))); }
function itineraryBudgetConfigured(entry){return Boolean(entry&&entry.coverageType==='Destination'&&(boolValue(entry.budgetConfigured,false)||Number(entry.budget||0)>0));}
