function currentItineraryEntry(){ return sortedItinerary().filter(x=>x.coverageType!=='Intentional Gap'&&itineraryClassification(x)==='current').sort((a,b)=>String(b.arrival).localeCompare(String(a.arrival)))[0]||null; }
