function selectedMapJourneys(){
  const baseJourneyYear=parseDate(state.settings.journeyStart)?.getFullYear()||2026;
  const horizonEnd=baseJourneyYear+MAX_JOURNEY_YEARS-1;
  const routes=[...completedJourneys()].filter(x=>{const y=Number(yearOfJourney(x));return Number.isFinite(y)&&y>=baseJourneyYear&&y<=horizonEnd;}).sort((a,b)=>String(a.start||'').localeCompare(String(b.start||'')));
  const availableYears=new Set(routes.map(x=>String(yearOfJourney(x))).filter(Boolean));
  const modeFiltered=mapModeFilters.has('All')||!mapModeFilters.size?routes:routes.filter(x=>mapModeFilters.has(normalizedTravelMode(x.type)));
  if(mapYearFilters.has('All')||!mapYearFilters.size) return modeFiltered;
  const validSelections=[...mapYearFilters].filter(year=>availableYears.has(String(year)));
  if(!validSelections.length){ mapYearFilters=new Set(['All']); return modeFiltered; }
  return modeFiltered.filter(x=>validSelections.includes(String(yearOfJourney(x))));
}
