function offlineGeoCandidates(value){
  const raw=String(value||'').trim(); if(!raw)return [];
  const parts=raw.split(/[,·|/]/).map(x=>x.trim()).filter(Boolean);
  const stripped=raw
    .replace(/\b(international )?airport\b/ig,'')
    .replace(/\b(central )?(railway |train )?station\b/ig,'')
    .replace(/\b(cruise |ferry )?(terminal|port|harbou?r)\b/ig,'')
    .replace(/\b(rv|motorhome|camper) (depot|pickup|return)\b/ig,'')
    .replace(/\s+/g,' ').trim();
  return [...new Set([raw,...parts,stripped])].filter(Boolean);
}
function offlineGeoLookup(value){
  for(const candidate of offlineGeoCandidates(value)){
    let key=geoKey(candidate); if(OFFLINE_GEO_ALIASES[key])key=OFFLINE_GEO_ALIASES[key];
    if(OFFLINE_GEO[key])return {key,coords:OFFLINE_GEO[key]};
  }
  return null;
}
function projectedPoint(lat,lon){
  const numericLat=Number(lat),numericLon=Number(lon);
  const safeLat=Number.isFinite(numericLat)?Math.max(-70,Math.min(75,numericLat)):0;
  const safeLon=Number.isFinite(numericLon)?Math.max(-180,Math.min(180,numericLon)):0;
  return clampMapPoint({x:((safeLon+180)/360)*100,y:((75-safeLat)/145)*100});
}

function clampMapPoint(point){
  const rawX=Number(point?.x),rawY=Number(point?.y);
  const x=Number.isFinite(rawX)?rawX:50,y=Number.isFinite(rawY)?rawY:50;
  return {x:Math.max(2.4,Math.min(97.6,x)),y:Math.max(4.4,Math.min(94.8,y))};
}
function storedMapPoint(record){
  const rawX=record?.mapX,rawY=record?.mapY;
  if(rawX===null||rawX===undefined||rawX===''||rawY===null||rawY===undefined||rawY==='')return null;
  const x=Number(rawX),y=Number(rawY);
  if(!Number.isFinite(x)||!Number.isFinite(y)||x<0||x>100||y<0||y>100)return null;
  /* Earlier builds could hydrate a blank pair as 0,0. Drag editing never saves
     that unclamped pair, so treat it as legacy-empty rather than a real point. */
  if(x===0&&y===0)return null;
  return {x,y};
}
function stableMapFallback(route,i,total){
  const seed=[route?.title,route?.country,route?.start,i,total].join('|');
  let hash=2166136261;
  for(const char of seed){hash^=char.charCodeAt(0);hash=Math.imul(hash,16777619);}
  const x=8+((hash>>>0)%8400)/100;
  const y=14+(((hash>>>8)>>>0)%6800)/100;
  return clampMapPoint({x,y});
}

