function routePoint(route,i,total){
  const manual=storedMapPoint(route);
  if(manual) return clampMapPoint(manual);
  const lat=Number(route?.lat), lon=Number(route?.lon);
  if(Number.isFinite(lat)&&Number.isFinite(lon)) return projectedPoint(lat,lon);
  const candidates=[route?.title,route?.city,route?.country,String(route?.title||'').split(',')[0],String(route?.title||'').split(',').slice(-1)[0]];
  for(const candidate of candidates){const found=offlineGeoLookup(candidate);if(found)return projectedPoint(...found.coords);}
  return null;
}
function normalizedTravelMode(type){
  const value=String(type||'').toLowerCase();
  return value.includes('motor')?'Motorhome':value.includes('cruise')?'Cruise':'Standard';
}
function routeColour(type){ const mode=normalizedTravelMode(type); return mode==='Motorhome'?'#f0a13d':mode==='Cruise'?'#4ea8ff':'#55d98a'; }
function journeyRouteColour(type){ const mode=normalizedTravelMode(type); return mode==='Motorhome'?'#78df5d':mode==='Cruise'?'#f2a11b':'#2cbcff'; }
function routeGeoCoordinates(route){
  const lat=Number(route?.lat),lon=Number(route?.lon);
  if(Number.isFinite(lat)&&Number.isFinite(lon)) return {lat:Math.max(-90,Math.min(90,lat)),lon:Math.max(-180,Math.min(180,lon))};
  const candidates=[route?.title,route?.city,route?.country,String(route?.title||'').split(',')[0],String(route?.title||'').split(',').slice(-1)[0]];
  for(const candidate of candidates){const found=offlineGeoLookup(candidate);if(found)return {lat:found.coords[0],lon:found.coords[1]};}
  return null;
}
function routeKilometres(a,b){
  const ga=routeGeoCoordinates(a),gb=routeGeoCoordinates(b);if(!ga||!gb)return null;
  const rad=x=>x*Math.PI/180,dLat=rad(gb.lat-ga.lat),dLon=rad(gb.lon-ga.lon);
  const rawQ=Math.sin(dLat/2)**2+Math.cos(rad(ga.lat))*Math.cos(rad(gb.lat))*Math.sin(dLon/2)**2;
  const q=Math.max(0,Math.min(1,rawQ));
  return Math.round(6371*2*Math.atan2(Math.sqrt(q),Math.sqrt(1-q)));
}
function routeBearing(a,b){
  const ga=routeGeoCoordinates(a),gb=routeGeoCoordinates(b);if(!ga||!gb)return null;
  if(Math.abs(ga.lat-gb.lat)<1e-9&&Math.abs(ga.lon-gb.lon)<1e-9)return null;
  const rad=x=>x*Math.PI/180,deg=x=>x*180/Math.PI,y=Math.sin(rad(gb.lon-ga.lon))*Math.cos(rad(gb.lat));
  const x=Math.cos(rad(ga.lat))*Math.sin(rad(gb.lat))-Math.sin(rad(ga.lat))*Math.cos(rad(gb.lat))*Math.cos(rad(gb.lon-ga.lon));
  return (Math.round(deg(Math.atan2(y,x)))+360)%360;
}
