function spreadMapPoints(points,minX=3.4,minY=5.5){
  const originals=points.map(clampMapPoint),placed=[];
  const clear=candidate=>placed.every(other=>Math.abs(candidate.x-other.x)>=minX||Math.abs(candidate.y-other.y)>=minY);
  originals.forEach(origin=>{
    let candidate={...origin};
    if(!clear(candidate)){
      const candidates=[];
      for(let ring=1;ring<=8;ring++){
        for(let gx=-ring;gx<=ring;gx++) for(let gy=-ring;gy<=ring;gy++){
          if(Math.max(Math.abs(gx),Math.abs(gy))!==ring)continue;
          const test=clampMapPoint({x:origin.x+gx*minX,y:origin.y+gy*minY});
          const score=(gx*minX)**2+(gy*minY)**2;
          candidates.push({test,score});
        }
      }
      candidates.sort((a,b)=>a.score-b.score);
      const found=candidates.find(item=>clear(item.test));
      if(found)candidate=found.test;
    }
    placed.push(candidate);
  });
  return placed;
}
function mapRouteGeometry(a,b,index=0){
  const rawDx=b.x-a.x;
  const wrap=Math.abs(rawDx)>52;
  const lift=Math.min(14,5+Math.abs(rawDx)*.075+(index%3)*1.2);
  const curve=(start,end)=>{
    const controlX=(start.x+end.x)/2;
    const controlY=Math.max(4,Math.min(96,(start.y+end.y)/2-lift));
    const d=`M ${start.x} ${start.y} Q ${controlX} ${controlY} ${end.x} ${end.y}`;
    const mx=(start.x+2*controlX+end.x)/4;
    const my=(start.y+2*controlY+end.y)/4;
    return {d,mx,my};
  };
  if(!wrap) return [curve(a,b)];
  const east=rawDx>0;
  const edgeA={x:east?0:100,y:(a.y+b.y)/2};
  const edgeB={x:east?100:0,y:(a.y+b.y)/2};
  return [curve(a,edgeB),curve(edgeA,b)];
}
function mapReadableRouteGeometry(a,b){
  const rawDx=b.x-a.x;
  const wrap=Math.abs(rawDx)>52;
  const line=(start,end)=>({d:`M ${start.x} ${start.y} L ${end.x} ${end.y}`,mx:(start.x+end.x)/2,my:(start.y+end.y)/2});
  if(!wrap)return [line(a,b)];
  const east=rawDx>0;
  const edgeA={x:east?0:100,y:(a.y+b.y)/2};
  const edgeB={x:east?100:0,y:(a.y+b.y)/2};
  return [line(a,edgeB),line(edgeA,b)];
}
