  const size=z*100,left=(1-z)*50+x,top=(1-z)*50+y;
  return `--map-zoom:${z};--map-pan-x:${x};--map-pan-y:${y};--map-render-size:${size}%;--map-layout-left:${left}%;--map-layout-top:${top}%;--pin-scale:1`;
