  const destinationAllocated=reservations.filter(x=>x.status!=='To Book'&&x.destinationBudget==='Yes').reduce((sum,x)=>sum+Number(x.aud||0),0);
  const annualAllocated=bookedTotal-destinationAllocated;
  const reservationStatusCounts={paid:reservations.filter(x=>x.status==='Paid').length,booked:reservations.filter(x=>x.status==='Booked').length,unpaid:reservations.filter(x=>x.status==='Unpaid').length,toBook:reservations.filter(x=>x.status==='To Book').length};
  const unpaidReservationTotal=reservations.filter(x=>x.status==='Unpaid').reduce((sum,x)=>sum+reservationAudValue(x),0);
  const periodRange=budgetPeriodRange();
