  if(reservationStatusFilter!=='All') filters.push(['Status',reservationStatusFilter]);
  if(reservationCountryFilter!=='All') filters.push(['Country',reservationCountryFilter]);
  if(reservationOnlyCurrent) filters.push(['Current country',state.currentStay.country||state.currentStay.city||'Current']);
  if(reservationDestinationFilter!=='All') filters.push(['Destination',reservationDestinationFilter]);
  if(reservationBudgetFilter!=='All') filters.push(['Budget',reservationBudgetFilter]);
  if(reservationCurrencyFilter!=='All') filters.push(['Currency',reservationCurrencyFilter]);
  if(reservationReferenceFilter!=='All') filters.push(['Reference',reservationReferenceFilter]);
  if(reservationOnlyUpcoming) filters.push(['View','Upcoming']);
  if(reservationShowCompleted) filters.push(['Archive','Shown']);
  if(reservationSearchQuery.trim()) filters.push(['Search',reservationSearchQuery.trim()]);
  if(reservationDateFrom) filters.push(['From',dateFmt(reservationDateFrom)]);
