function reservationDateOverlap(a,b){
  if(!a?.date||!b?.date||a.id===b.id||a.status==='To Book'||b.status==='To Book') return false;
  const occupancyTypes=MULTI_DAY_RESERVATION_TYPES;
  if(!occupancyTypes.has(a.type)||!occupancyTypes.has(b.type)) return false;
  const aEnd=a.endDate||a.date,bEnd=b.endDate||b.date;
  if(a.date===aEnd&&b.date===bEnd) return a.date===b.date;
  return a.date<bEnd&&b.date<aEnd;
}
function reservationConflictIds(rows=state.reservations){
  const ids=new Set();
  for(let i=0;i<rows.length;i++)for(let j=i+1;j<rows.length;j++)if(reservationDateOverlap(rows[i],rows[j])){ids.add(rows[i].id);ids.add(rows[j].id);}
  return ids;
}
function reservationBusiestMonth(rows){
  const counts={};
  rows.filter(x=>x.date).forEach(x=>{const key=x.date.slice(0,7);counts[key]=(counts[key]||0)+1;});
  const best=Object.entries(counts).sort((a,b)=>b[1]-a[1]||a[0].localeCompare(b[0]))[0];
  if(!best)return {label:'No bookings',count:0};
  const d=new Date(`${best[0]}-01T12:00:00`);
  return {label:d.toLocaleDateString('en-AU',{month:'short',year:'numeric'}),count:best[1]};
}
function copyReservationSummary(rows){
  const booked=rows.filter(x=>x.status!=='To Book');
  const total=booked.reduce((sum,x)=>sum+reservationAudValue(x),0);
  const unpaid=rows.filter(x=>x.status==='Unpaid').reduce((sum,x)=>sum+reservationAudValue(x),0);
  const text=[`Reservations: ${rows.length}`,`Booked value: ${money(total)}`,`Unpaid: ${money(unpaid)}`,`Upcoming: ${rows.filter(x=>!reservationIsCompleted(x)&&x.status!=='To Book').length}`,`To Book: ${rows.filter(x=>x.status==='To Book').length}`].join('\n');
  if(navigator.clipboard?.writeText)return navigator.clipboard.writeText(text).then(()=>showToast('Reservation summary copied.')).catch(()=>showToast('Could not copy the summary.','error'));
  const area=document.createElement('textarea');area.value=text;document.body.append(area);area.select();document.execCommand('copy');area.remove();showToast('Reservation summary copied.');
}

