const DELETABLE_COLLECTIONS=new Set(['expenses','reservations','events','journeys','itinerary','checklist','vault','streamingCodes','alerts','accounts']);
function deleteRecordLabel(type,record){
  const fallback={expenses:'expense',reservations:'reservation',events:'calendar event',journeys:'journey',itinerary:'itinerary entry',checklist:'checklist item',vault:'vault record',alerts:'alert',accounts:'account'}[type]||'item';
  const name=record?.title||record?.task||record?.name||record?.city||record?.category||'';
  return name ? `${fallback} “${name}”` : fallback;
}
async function requestDelete(type,id){
  if(!DELETABLE_COLLECTIONS.has(type)||!Array.isArray(state[type])){showToast('This item cannot be deleted.','error');return;}
  const record=state[type].find(x=>x.id===id);
  if(!record){showToast('The item could not be found.','error');return;}
  const label=deleteRecordLabel(type,record);
  const verifiedNote=record.verified?' This verified record will be permanently removed.':'';
  const ok=await confirmAction(`Delete ${label}?${verifiedNote} This cannot be undone.`,{title:'Confirm deletion',accept:'Delete'});
  if(!ok){showToast('Deletion cancelled.','warning');return;}
  setButtonBusy(confirmAccept,true,'Deleting…');
  state[type]=state[type].filter(x=>x.id!==id);
  if(type==='itinerary'){
    state.reservations=state.reservations.map(item=>String(item.itineraryId||'')===String(id)?{...item,itineraryId:''}:item);
    state.journeys=state.journeys.filter(item=>String(item.sourceItineraryId||'')!==String(id));
  }
  saveState(type,'delete');
  showToast(`${label.charAt(0).toUpperCase()+label.slice(1)} deleted.`);
}

