function mapKind(kind){ return ({budget:'expenses',calendar:'events',reservations:'reservations',itinerary:'itinerary',journeys:'journeys',checklist:'checklist',vault:'vault',alerts:'alerts'}[kind]||kind); }
function loadImageFile(file){
  return new Promise((resolve,reject)=>{
    const image=new Image(),url=URL.createObjectURL(file);
    image.onload=()=>{URL.revokeObjectURL(url);resolve(image);};
    image.onerror=()=>{URL.revokeObjectURL(url);reject(new Error(`Could not read ${file.name}.`));};
    image.src=url;
  });
}
function canvasBlob(canvas,type='image/jpeg',quality=.82){
  return new Promise((resolve,reject)=>canvas.toBlob(blob=>blob?resolve(blob):reject(new Error('Could not compress screenshot.')),type,quality));
}
function blobDataUrl(blob){
  return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(new Error('Could not store compressed screenshot.'));reader.readAsDataURL(blob);});
}
async function compressVaultScreenshot(file){
  const image=await loadImageFile(file);
  let scale=Math.min(1,1600/Math.max(image.naturalWidth||1,image.naturalHeight||1));
  let width=Math.max(1,Math.round(image.naturalWidth*scale)),height=Math.max(1,Math.round(image.naturalHeight*scale));
  let quality=.82,blob=null;
  for(let attempt=0;attempt<8;attempt++){
    const canvas=document.createElement('canvas');canvas.width=width;canvas.height=height;
    const context=canvas.getContext('2d',{alpha:false});context.fillStyle='#ffffff';context.fillRect(0,0,width,height);context.drawImage(image,0,0,width,height);
    blob=await canvasBlob(canvas,'image/jpeg',quality);
    if(blob.size<=MAX_VAULT_ATTACHMENT_BYTES) break;
    if(quality>.52) quality-=.09; else {width=Math.max(640,Math.round(width*.84));height=Math.max(400,Math.round(height*.84));}
  }
  if(!blob||blob.size>MAX_VAULT_ATTACHMENT_BYTES*1.35) throw new Error(`${file.name} could not be compressed enough for reliable offline storage.`);
  return {id:uid(),name:file.name.replace(/\.(png|webp)$/i,'.jpg'),type:'image/jpeg',size:blob.size,originalSize:file.size,width,height,data:await blobDataUrl(blob)};
}
async function readVaultScreenshots(fileList){
  const files=[...fileList].slice(0,6);
  const allowed=['image/png','image/jpeg','image/webp'];
  if(files.some(file=>!allowed.includes(file.type))) throw new Error('Only PNG, JPEG or WebP screenshots can be stored.');
  if(files.some(file=>file.size>MAX_VAULT_SOURCE_BYTES)) throw new Error('Each source screenshot must be smaller than 8 MB.');
  const output=[];
  for(const file of files) output.push(await compressVaultScreenshot(file));
  return output;
}
function showVaultAttachments(id){
  const record=state.vault.find(x=>x.id===id);const attachments=Array.isArray(record?.attachments)?record.attachments:[];
  if(!record||!attachments.length){showToast('No screenshots are attached to this record.','warning');return;}
  const win=window.open('','_blank');
  if(!win){showToast('Safari blocked the screenshot viewer.','warning');return;}
  win.document.write(`<title>${esc(record.name)} screenshots</title><meta name="viewport" content="width=device-width"><style>body{margin:0;padding:20px;background:#06111d;color:#eef8ff;font-family:system-ui}h1{font-size:22px}figure{margin:18px 0;padding:12px;border:1px solid #315574;border-radius:12px;background:#0b1b2d}img{max-width:100%;height:auto;display:block;margin:auto}figcaption{padding-top:8px;color:#a9bed0}</style><h1>${esc(record.name)}</h1>${attachments.map(a=>`<figure><img src="${a.data}" alt="${esc(a.name)}"><figcaption>${esc(a.name)}</figcaption></figure>`).join('')}`);win.document.close();
}


function expenseDefaultDate(){return itineraryReferenceDate();}
function expenseContextForDate(date){
  const entry=itineraryOwnerForDate(validISODate(date)?date:itineraryReferenceDate());
  if(entry)return {currency:entry.currency||'AUD',symbol:entry.symbol??'',rate:finiteNumber(entry.rate,1,.000001,1_000_000),itineraryId:entry.id};
  return {currency:'AUD',symbol:'$',rate:1,itineraryId:''};
}

