let expandedMapGesture=null;
function touchDistance(a,b){return Math.hypot(b.clientX-a.clientX,b.clientY-a.clientY);}
function clampPan(value,zoom){const limit=Math.max(12,(zoom-1)*50);return Math.max(-limit,Math.min(limit,value));}
document.addEventListener('touchstart',event=>{
  const itineraryShell=event.target.closest?.('.itinerary-map-shell.full-page-map');
  const journeyShell=event.target.closest?.('.journey-expanded-map-page .journey-map-shell.full-page-map');
  const shell=itineraryShell||journeyShell;if(!shell||!event.touches.length)return;
  if(event.target.closest?.('.geo-pin,.map-tools,.map-filters,.map-mode-filters'))return;
  const touches=[...event.touches],a=touches[0],b=touches[1]||a;
  const isItinerary=Boolean(itineraryShell),zoom=isItinerary?itineraryMapZoom:mapZoom,panX=isItinerary?itineraryMapPanX:mapPanX,panY=isItinerary?itineraryMapPanY:mapPanY;
  expandedMapGesture={kind:isItinerary?'itinerary':'journey',shell,x:(a.clientX+b.clientX)/2,y:(a.clientY+b.clientY)/2,startDistance:touches.length>1?touchDistance(a,b):0,zoom,panX,panY,moved:false};
},{passive:true});
document.addEventListener('touchmove',event=>{
  const g=expandedMapGesture;if(!g||!event.touches.length)return;
  const touches=[...event.touches],a=touches[0],b=touches[1]||a,rect=g.shell.getBoundingClientRect();
  const x=(a.clientX+b.clientX)/2,y=(a.clientY+b.clientY)/2;
  let zoom=g.zoom;
  if(touches.length>1&&g.startDistance>4) zoom=Math.max(1,Math.min(6,g.zoom*(touchDistance(a,b)/g.startDistance)));
  const nextX=clampPan(g.panX+(x-g.x)/Math.max(1,rect.width)*100,zoom);
  const nextY=clampPan(g.panY+(y-g.y)/Math.max(1,rect.height)*100,zoom);
  if(Math.abs(x-g.x)>2||Math.abs(y-g.y)>2||Math.abs(zoom-g.zoom)>.01)g.moved=true;
  if(g.kind==='itinerary'){itineraryMapZoom=zoom;itineraryMapPanX=nextX;itineraryMapPanY=nextY;itineraryMapPanTouched=true;}
  else{mapZoom=zoom;mapPanX=nextX;mapPanY=nextY;mapPanTouched=true;}
  const viewport=g.shell.querySelector('.journey-map-viewport');applyExpandedMapViewportStyle(viewport,zoom,nextX,nextY);
  const resetButton=g.shell.closest('section')?.querySelector(g.kind==='itinerary'?'[data-itinerary-map-zoom="reset"]':'[data-map-zoom="reset"]');if(resetButton)resetButton.textContent='FIT ROUTE';
  event.preventDefault();
},{passive:false});
document.addEventListener('touchend',event=>{if(!event.touches.length)expandedMapGesture=null;},{passive:true});

let expandedPointerPan=null;
document.addEventListener('pointerdown',event=>{
  if(event.pointerType==='touch')return;
  const shell=event.target.closest?.('.itinerary-map-shell.full-page-map,.journey-expanded-map-page .journey-map-shell.full-page-map');
  if(!shell||event.target.closest?.('.geo-pin,.map-tools,.map-filters,.map-mode-filters'))return;
  const isItinerary=shell.classList.contains('itinerary-map-shell');
  expandedPointerPan={shell,kind:isItinerary?'itinerary':'journey',id:event.pointerId,x:event.clientX,y:event.clientY,panX:isItinerary?itineraryMapPanX:mapPanX,panY:isItinerary?itineraryMapPanY:mapPanY,zoom:isItinerary?itineraryMapZoom:mapZoom};
  shell.setPointerCapture?.(event.pointerId);event.preventDefault();
});
document.addEventListener('pointermove',event=>{
  const g=expandedPointerPan;if(!g||g.id!==event.pointerId)return;const rect=g.shell.getBoundingClientRect();
  const x=clampPan(g.panX+(event.clientX-g.x)/Math.max(1,rect.width)*100,g.zoom),y=clampPan(g.panY+(event.clientY-g.y)/Math.max(1,rect.height)*100,g.zoom);
  if(g.kind==='itinerary'){itineraryMapPanX=x;itineraryMapPanY=y;itineraryMapPanTouched=true;}else{mapPanX=x;mapPanY=y;mapPanTouched=true;}
  const viewport=g.shell.querySelector('.journey-map-viewport');applyExpandedMapViewportStyle(viewport,g.zoom,x,y);event.preventDefault();
});
document.addEventListener('pointerup',event=>{if(expandedPointerPan?.id===event.pointerId)expandedPointerPan=null;});

function globalSearchMatches(query=globalSearchQuery){
  const q=String(query||'').trim().toLowerCase();
  if(!q) return [];
  const found=[];
  const add=(label,sub,target,edit='')=>{if((label+' '+sub).toLowerCase().includes(q)) found.push({label,sub,target,edit});};
  state.reservations.forEach(x=>add(x.title,`${x.type} ${x.status||''} ${x.notes||''}`,'reservations',`reservations:${x.id}`));
  state.itinerary.forEach(x=>add(itineraryTitle(x),`${x.type} ${x.country||''} ${x.notes||''}`,'itinerary',`itinerary:${x.id}`));
  state.journeys.forEach(x=>add(x.title,`${x.type} ${x.notes||''}`,'journeys',`journeys:${x.id}`));
  state.vault.forEach(x=>add(x.name,`${x.type} ${x.identityKind||''} ${x.owner||''} ${x.country||''} ${x.reference||''} ${x.insuranceProvider||''} ${x.assistancePhone||''} ${x.visaEntries||''} ${x.permittedStayDays||''} ${x.notes||''}`,'vault',`vault:${x.id}`));
  state.events.forEach(x=>add(x.title,x.notes||'','calendar',`events:${x.id}`));
  state.expenses.forEach(x=>add(x.category,`${x.currency||''} ${x.notes||''}`,'budget',`expenses:${x.id}`));
  state.checklist.forEach(x=>add(x.task,`${x.list||''} ${x.notes||''}`,'checklist',`checklist:${x.id}`));
  add(`${state.currentStay.city}, ${state.currentStay.country}`,`${state.currentStay.currency} current destination`,'dashboard','stay');
  return found.slice(0,8);
}
function refreshGlobalSearch(){
  const input=$('#global-search'), results=$('#global-results');
  if(!input||!results) return;
  input.value=globalSearchQuery;
  if(!globalSearchQuery){results.innerHTML='';return;}
  const found=globalSearchMatches(globalSearchQuery);
  results.innerHTML=found.map(x=>`<button data-search-target="${x.target}" data-search-edit="${esc(x.edit)}"><b>${esc(x.label)}</b><small>${esc(x.sub)}</small></button>`).join('')||empty('No matching records.');
  results.querySelectorAll('[data-search-target]').forEach(button=>button.onclick=()=>{const target=button.dataset.searchTarget,edit=button.dataset.searchEdit;globalSearchQuery='';screen=target;render();requestAnimationFrame(resetScreenScroll);if(edit==='stay'){const active=currentItineraryEntry(),date=itineraryReferenceDate();active?openForm('itinerary',active.id):openForm('itinerary',null,{coverageType:'Destination',arrival:date,departure:date});}else if(edit){const[type,id]=edit.split(':');openForm(type,id);}});
}
function bindGlobalSearch(){
  const input=$('#global-search');
  if(!input) return;
  input.value=globalSearchQuery;
  input.oninput=()=>{globalSearchQuery=input.value;refreshGlobalSearch();};
  refreshGlobalSearch();
}

function downloadBlob(blob,filename){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=filename;document.body.append(a);a.click();const url=a.href;a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportReservationRows(rows){
  if(!rows.length) return showToast('No matching reservations to export.','warning');
  const header=['Title','Type','Destination','Start Date','End Date','Status','Currency','Original Cost','AUD Cost','Budget','Reference','Travellers','Notes'];
  const csv=[header,...rows.map(x=>[x.title,x.type,reservationDestination(x),x.date||'',x.endDate||'',x.status,x.currency||'',Number(x.original||0),reservationAudValue(x),x.destinationBudget==='Yes'?'Destination':'Annual',x.reference||'',Math.max(1,Number(x.travellers||2)),x.notes||''])].map(row=>row.map(v=>`"${String(v??'').replaceAll('\"','\"\"')}"`).join(',')).join('\n');
  downloadBlob(new Blob([csv],{type:'text/csv;charset=utf-8'}),`travel-command-centre-reservations-${itineraryReferenceDate()}.csv`);
  showToast(`${rows.length} reservation${rows.length===1?'':'s'} exported.`);
}

