  if(pinInput)pinInput.oninput=()=>{pinInput.value=pinInput.value.replace(/\D/g,'').slice(0,4);};
  if(savePin)savePin.onclick=()=>{const enabled=Boolean(pinToggle?.checked),pin=String(pinInput?.value||'').trim();if(enabled&&!/^\d{4}$/.test(pin)){showToast('PIN must be exactly four numbers.','warning');return;}state.settings={...state.settings,pinEnabled:enabled,pin:enabled?pin:'',lastSettingsSaved:appDateTimeLabel()};saveState('settings','pin');showToast(enabled?'PIN saved.':'PIN turned off.');render();};
  if(lockNow)lockNow.onclick=()=>{if(!state.settings.pinEnabled||!state.settings.pin){showToast('Turn on and save a PIN first.','warning');return;}sessionStorage.removeItem('tccUnlocked');location.reload();};
