function budgetVerificationIssues(){
  syncLinkedState();
  const issues=[];
  if(!Number.isFinite(staySpendLocal())||!Number.isFinite(annualSpendAud()))issues.push('Linked totals could not be calculated.');
  if(Number(state.currentStay.rate)<=0)issues.push('Exchange rate must be above zero.');
  if(Number(state.currentStay.budget)<0)issues.push('Destination budget cannot be negative.');
  if(annualBudgetForYear()<0)issues.push('Annual budget cannot be negative.');
  state.expenses.forEach((x,i)=>{if(Number(x.amount)<0)issues.push(`Expense ${i+1} is negative.`);if(Number(x.rate)<=0)issues.push(`Expense ${i+1} has an invalid exchange rate.`);});
  state.reservations.forEach((x,i)=>{if(Math.abs(Number(x.aud||0)-reservationAudValue(x))>.01)issues.push(`Reservation ${i+1} AUD total is out of sync.`);});
  return issues;
}
function verifyBudget(){
  const issues=budgetVerificationIssues();
  const el=$('#budget-check');
  if(el){
    el.className=issues.length?'warning':'success';
    el.textContent=issues.length?issues.join(' · '):`Budget verification passed. Destination spend ${localMoney(staySpendLocal(),state.currentStay.symbol)} (≈ ${money(staySpendAud())}); annual spend ${money(annualSpendAud())}.`;
  }
  return issues;
}
function verifyAndLockBudget(){
  const issues=verifyBudget();
  if(issues.length){showToast('Budget verification found invalid values.','error');return false;}
  const entry=activeDestinationItinerary();
  state.expenses=state.expenses.map(x=>entry&&recordBelongsToItinerary(x,entry,'expense')?{...x,verified:true}:x);
  state.reservations=state.reservations.map(x=>entry&&recordBelongsToItinerary(x,entry,'reservation')?{...x,verified:true}:x);
  state.settings.lastVerified=itineraryReferenceDate();
  state.settings.lastBudgetVerifiedAt=appDateTimeLabel();
  saveState('verification','verify-budget');
  showToast('Budget calculations verified and current-stay records locked.');
  return true;
}
function reservationHealthChecks(){
  const rows=state.reservations;
  const refs=reservationReferenceCounts(rows);
  const duplicateKeys=new Set();
  const seenKeys=new Set();
  rows.forEach(x=>{const key=[String(x.title||'').trim().toLowerCase(),x.date||'',x.type||''].join('|');if(seenKeys.has(key))duplicateKeys.add(key);else seenKeys.add(key);});
  const conflictIds=reservationConflictIds(rows);
  const validTypes=['Accommodation','Hotel','Airbnb','Flight','Train','Cruise','RV','Tickets & Attractions'];
  const validStatuses=['Paid','Booked','Unpaid','To Book'];
  const detailMissing=rows.filter(x=>!x.title||!x.type||!x.date);
  const destinationMissing=rows.filter(x=>reservationDestinationText(x)==='Unassigned');
  const badDateOrder=rows.filter(x=>x.endDate&&x.date&&x.endDate<x.date);
  const badCurrency=rows.filter(x=>x.currency&&!/^[A-Za-z]{3}$/.test(String(x.currency).trim()));
  const negativeCost=rows.filter(x=>Number(x.original||0)<0);
  const badRate=rows.filter(x=>Number(x.original||0)>0&&Number(x.rate||0)<=0);
  const audMismatch=rows.filter(x=>Math.abs(Number(x.aud||0)-reservationAudValue(x))>.01);
  const badBudget=rows.filter(x=>!['Yes','No',undefined].includes(x.destinationBudget));
  const missingBudgetDestination=rows.filter(x=>x.destinationBudget==='Yes'&&reservationDestinationText(x)==='Unassigned');
  const badStatus=rows.filter(x=>!validStatuses.includes(x.status));
  const badType=rows.filter(x=>!validTypes.includes(x.type));
  const badTravellers=rows.filter(x=>!Number.isInteger(Number(x.travellers||2))||Number(x.travellers||2)<1);
  const duplicateReferences=rows.filter(x=>{const key=String(x.reference||'').trim().toLowerCase();return key&&refs[key]>1;});
  const likelyDuplicates=rows.filter(x=>duplicateKeys.has([String(x.title||'').trim().toLowerCase(),x.date||'',x.type||''].join('|')));
  const conflicts=rows.filter(x=>conflictIds.has(x.id));
  const missingEnd=rows.filter(x=>MULTI_DAY_RESERVATION_TYPES.has(x.type)&&!x.endDate);
  const overdueUnpaid=rows.filter(reservationIsOverdue);
  const zeroCostConfirmed=rows.filter(x=>x.status!=='To Book'&&reservationAudValue(x)===0);
  const missingReference=rows.filter(x=>x.status!=='To Book'&&!String(x.reference||'').trim());
  const missingNotes=rows.filter(x=>!String(x.notes||'').trim());
  const make=(label,items,message,severity='warning')=>({label,ok:items.length===0,count:items.length,message,severity,items});
  return [
    make('Required details',detailMissing,'missing required title, type or start date','error'),
    make('Destinations present',destinationMissing,'missing destination','error'),
    make('Date order valid',badDateOrder,'end date is before start date','error'),
    make('Currency codes valid',badCurrency,'currency must use a 3-letter code','error'),
    make('Costs non-negative',negativeCost,'cost cannot be negative','error'),
    make('Exchange rates valid',badRate,'positive local cost needs a valid exchange rate','error'),
    make('AUD totals accurate',audMismatch,'saved AUD total does not match cost × rate','error'),
    make('Budget assignments valid',badBudget,'budget assignment is invalid','error'),
    make('Destination budgets linked',missingBudgetDestination,'destination budget needs a destination','error'),
    make('Statuses valid',badStatus,'status is not recognised','error'),
    make('Reservation types valid',badType,'reservation type is not recognised','error'),
    make('Traveller counts valid',badTravellers,'traveller count must be a positive whole number','error'),
    make('References unique',duplicateReferences,'booking reference is duplicated'),
    make('No likely duplicates',likelyDuplicates,'same title, type and date appears more than once'),
    make('No date conflicts',conflicts,'confirmed booking dates overlap'),
    make('Long bookings have end dates',missingEnd,'accommodation, cruise or RV record has no end date'),
    make('No overdue unpaid items',overdueUnpaid,'unpaid reservation is overdue'),
    make('Confirmed costs recorded',zeroCostConfirmed,'confirmed reservation has zero AUD cost'),
    make('Confirmed references recorded',missingReference,'confirmed reservation has no booking reference'),
    make('Notes coverage complete',missingNotes,'reservation has no notes','info')
  ];
}
function reservationHealthIssues(){
  const issues=[];
  reservationHealthChecks().filter(check=>!check.ok).forEach(check=>{
    check.items.forEach((x,i)=>{
      const label=x.title||`Reservation ${i+1}`;
      issues.push(`${label}: ${check.message}.`);
    });
  });
  return [...new Set(issues)];
}

function renderReservationHealthResult(){
  const checks=reservationHealthChecks();
  const issues=reservationHealthIssues();
  const failed=checks.filter(x=>!x.ok);
  const errors=failed.filter(x=>x.severity==='error').length;
  const warnings=failed.filter(x=>x.severity==='warning').length;
  const information=failed.filter(x=>x.severity==='info').length;
  const stateClass=errors?'danger':warnings?'warning':'success';
  const headline=issues.length?`${failed.length} check${failed.length===1?'':'s'} need attention`:'Reservations OK';
  const detail=issues.length?`${errors} critical · ${warnings} warning · ${information} information`:'20 of 20 checks passed';
  return `<div id="reservation-check-result" class="reservation-health-result compact ${stateClass}"><div class="reservation-health-status-card"><span class="health-status-icon">${issues.length?'!':'✓'}</span><div><small>RESERVATION STATUS</small><b>${esc(headline)}</b><em>${esc(detail)}</em></div><time>${esc(reservationLastCheckLabel())}</time></div><details class="health-details"><summary>${issues.length?'View items to fix':'View check details'} <span>⌄</span></summary><div class="health-check-grid reservation-audit-grid">${checks.map(check=>`<span class="${check.ok?'ok':check.severity==='error'?'bad':check.severity==='info'?'info':'warn'}" title="${check.ok?'Passed':esc(check.message)}">${check.ok?'✓':'!'} ${esc(check.label)}${check.ok?'':` (${check.count})`}</span>`).join('')}</div>${issues.length?`<p>${esc(issues.slice(0,5).join(' · '))}${issues.length>5?` · plus ${issues.length-5} more`:''}</p>`:''}</details></div>`;
}
