function validateBackup(data){
  const errors=[];
  if(!data||typeof data!=='object'||Array.isArray(data)) return ['File is not a Travel Command Centre object.'];
  const collections=['expenses','reservations','events','journeys','checklist','vault','alerts','accounts'];
  for(const key of collections) if(!Array.isArray(data[key])) errors.push(`${key} is missing or invalid.`);
  if(data.itinerary!==undefined&&!Array.isArray(data.itinerary)) errors.push('itinerary is invalid.');
  if(!data.currentStay||typeof data.currentStay!=='object'||!data.settings||typeof data.settings!=='object') errors.push('Settings or current stay are missing.');
  if(data.settings?.currentDateTime!==undefined&&!validLocalDateTime(data.settings.currentDateTime)) errors.push('Current destination date and time are invalid.');
  const annualBudgetValues=data.annualBudgets&&typeof data.annualBudgets==='object'&&!Array.isArray(data.annualBudgets)?Object.values(data.annualBudgets):[data.annualBudget];
  if(!annualBudgetValues.length||annualBudgetValues.some(value=>!Number.isFinite(Number(value))||Number(value)<0||Number(value)>1_000_000_000)) errors.push('Annual budget history is missing, invalid or negative.');
  const stay=data.currentStay||{};
  if(!validISODate(stay.start)||!validISODate(stay.end)||stay.end<stay.start) errors.push('Current stay dates are invalid.');
  if(!String(stay.city||'').trim()||!String(stay.country||'').trim()) errors.push('Current stay city or country is missing.');
  if(!Number.isFinite(Number(stay.rate))||Number(stay.rate)<=0) errors.push('Current stay exchange rate is invalid.');
  if(!Number.isFinite(Number(stay.budget))||Number(stay.budget)<0) errors.push('Current stay budget is invalid.');
  (Array.isArray(data.expenses)?data.expenses:[]).forEach((x,i)=>{if(!validISODate(x.date))errors.push(`Expense ${i+1} date is invalid.`);if(!Number.isFinite(Number(x.amount))||Number(x.amount)<=0||Number(x.amount)>1_000_000_000)errors.push(`Expense ${i+1} amount is invalid.`);if(!Number.isFinite(Number(x.rate))||Number(x.rate)<=0||Number(x.rate)>1_000_000)errors.push(`Expense ${i+1} rate is invalid.`);if(x.currency!==undefined&&!/^[A-Za-z]{3}$/.test(String(x.currency||'')))errors.push(`Expense ${i+1} currency is invalid.`);});
  (Array.isArray(data.reservations)?data.reservations:[]).forEach((x,i)=>{if(!validISODate(x.date))errors.push(`Reservation ${i+1} date is invalid.`);if(x.endDate&&(!validISODate(x.endDate)||x.endDate<x.date))errors.push(`Reservation ${i+1} end date is invalid.`);if(!Number.isFinite(Number(x.original))||Number(x.original)<0||Number(x.original)>1_000_000_000||!Number.isFinite(Number(x.rate))||Number(x.rate)<=0||Number(x.rate)>1_000_000)errors.push(`Reservation ${i+1} cost or rate is invalid.`);if(x.currency!==undefined&&!/^[A-Za-z]{3}$/.test(String(x.currency||'')))errors.push(`Reservation ${i+1} currency is invalid.`);if(!['Paid','Unpaid','Booked','To Book'].includes(x.status))errors.push(`Reservation ${i+1} status is invalid.`);});
  (Array.isArray(data.events)?data.events:[]).forEach((x,i)=>{if(!validISODate(x.date))errors.push(`Calendar event ${i+1} date is invalid.`);});
  (Array.isArray(data.itinerary)?data.itinerary:[]).forEach((x,i)=>{if(!validISODate(x.arrival)||!validISODate(x.departure)||x.departure<x.arrival)errors.push(`Itinerary entry ${i+1} dates are invalid.`);if((x.coverageType||'Destination')==='Destination'&&itineraryMode(x.type)==='Standard'&&(!String(x.city||'').trim()||!String(x.country||'').trim()))errors.push(`Itinerary entry ${i+1} destination is incomplete.`);if(x.currency!==undefined&&!/^[A-Za-z]{3}$/.test(String(x.currency||'')))errors.push(`Itinerary entry ${i+1} currency is invalid.`);if(String(x.symbol||'').length>8)errors.push(`Itinerary entry ${i+1} currency symbol is too long.`);if(!Number.isFinite(Number(x.rate))||Number(x.rate)<=0||Number(x.rate)>1_000_000||!Number.isFinite(Number(x.budget))||Number(x.budget)<0||Number(x.budget)>1_000_000_000)errors.push(`Itinerary entry ${i+1} budget or rate is invalid.`);if((x.mapX!==undefined&&x.mapX!==null&&(!Number.isFinite(Number(x.mapX))||Number(x.mapX)<0||Number(x.mapX)>100))||(x.mapY!==undefined&&x.mapY!==null&&(!Number.isFinite(Number(x.mapY))||Number(x.mapY)<0||Number(x.mapY)>100)))errors.push(`Itinerary entry ${i+1} map position is invalid.`);});
  (Array.isArray(data.journeys)?data.journeys:[]).forEach((x,i)=>{if(!validISODate(x.start)||!validISODate(x.end)||x.end<x.start)errors.push(`Journey ${i+1} dates are invalid.`);if(!Number.isFinite(Number(x.spend||0))||Number(x.spend||0)<0||!Number.isFinite(Number(x.km||0))||Number(x.km||0)<0)errors.push(`Journey ${i+1} totals are invalid.`);if(!['Standard stay','Motorhome','Cruise'].includes(x.type||'Standard stay'))errors.push(`Journey ${i+1} travel type is invalid.`);});
  (Array.isArray(data.checklist)?data.checklist:[]).forEach((x,i)=>{if(!String(x.task||'').trim())errors.push(`Checklist item ${i+1} is missing its task.`);if(x.due&&!validISODate(x.due))errors.push(`Checklist item ${i+1} due date is invalid.`);});
  (Array.isArray(data.vault)?data.vault:[]).forEach((x,i)=>{if(!String(x.name||'').trim())errors.push(`Vault record ${i+1} is missing its name.`);if(x.expiry&&!validISODate(x.expiry))errors.push(`Vault record ${i+1} expiry date is invalid.`);if(x.attachments&&(!Array.isArray(x.attachments)||x.attachments.length>6||x.attachments.some(a=>!/^data:image\/(png|jpeg|webp);base64,/i.test(String(a?.data||''))||String(a?.data||'').length>Math.ceil(MAX_VAULT_ATTACHMENT_BYTES*1.5))))errors.push(`Vault record ${i+1} screenshot data is invalid.`);});
  const ids=[];for(const key of [...collections,'itinerary'])for(const record of (Array.isArray(data[key])?data[key]:[])){if(record?.id!==undefined){const id=String(record.id);if(!/^[A-Za-z0-9._:-]{1,128}$/.test(id))errors.push(`${key} contains an unsafe record identifier.`);ids.push(`${key}:${id}`);}}
  if(new Set(ids).size!==ids.length)errors.push('The backup contains duplicate record identifiers.');
  const vaultChars=(Array.isArray(data.vault)?data.vault:[]).reduce((sum,record)=>sum+(Array.isArray(record.attachments)?record.attachments.reduce((n,a)=>n+String(a?.data||'').length,0):0),0);
  if(vaultChars>MAX_VAULT_DATA_CHARS)errors.push('Vault screenshot data exceeds the reliable offline storage limit.');
  return [...new Set(errors)].slice(0,60);
}
function restoreFile(e){
  const file=e.target.files[0]; if(!file)return;
  if(file.size>25*1024*1024){showToast('Restore failed: backup file is larger than 25 MB.','error');e.target.value='';return;}
  const r=new FileReader();
  r.onload=async()=>{
    try{
      const data=JSON.parse(r.result),errors=validateBackup(data); if(errors.length)throw Error(errors.join(' '));
      const ok=await confirmAction('Restore this backup and replace all current local data?',{title:'Restore backup',accept:'Restore'}); if(!ok){showToast('Restore cancelled.','warning');return;}
      const restored=await withGlobalLoading('Restoring backup…',async()=>{state=hydrate(data);return saveState('restore','replace');}); if(!restored)throw Error(lastStorageError||'The backup could not be stored.'); showToast('Backup restored successfully.');
    }catch(err){showToast(`Restore failed: ${err.message}`,'error');}
  };
  r.onerror=()=>showToast('Restore failed: Safari could not read this file.','error');
  r.readAsText(file); e.target.value='';
}
function runVerify(){
  const issues=[];
  try{localStorage.setItem('__tcc_test','1');localStorage.removeItem('__tcc_test');}catch{issues.push('Local storage unavailable.');}
  for(const k of ['expenses','reservations','events','journeys','itinerary','checklist','vault','streamingCodes','accounts']) if(!Array.isArray(state[k])) issues.push(`${k} collection invalid.`);
  if(!validLocalDateTime(state.settings.currentDateTime)) issues.push('Current destination date and time are invalid.');
  if(Number(state.currentStay.rate)<=0) issues.push('Exchange rate must be above zero.');
  if(Number(state.currentStay.budget)<0||annualBudgetForYear()<0) issues.push('Budgets cannot be negative.');
  if(!validISODate(state.currentStay.start)||!validISODate(state.currentStay.end)||state.currentStay.end<state.currentStay.start) issues.push('Current planning dates are invalid.');
  state.itinerary.forEach((x,i)=>{if(!validISODate(x.arrival)||!validISODate(x.departure)||x.departure<x.arrival)issues.push(`Itinerary ${i+1} dates are invalid.`);if(x.coverageType!=='Intentional Gap'&&itineraryMode(x.type)==='Standard'&&(!x.city||!x.country))issues.push(`Itinerary ${i+1} destination is incomplete.`);if(Number(x.rate)<=0||Number(x.budget)<0)issues.push(`Itinerary ${i+1} rate or budget is invalid.`);if((x.mapX!==null&&x.mapX!==undefined&&(!Number.isFinite(Number(x.mapX))||Number(x.mapX)<0||Number(x.mapX)>100))||(x.mapY!==null&&x.mapY!==undefined&&(!Number.isFinite(Number(x.mapY))||Number(x.mapY)<0||Number(x.mapY)>100)))issues.push(`Itinerary ${i+1} map position is invalid.`);});
  const coverage=itineraryCoverage(itineraryReferenceDate(),12);if(coverage.overlaps.length)issues.push(`${coverage.overlaps.length} itinerary overlap${coverage.overlaps.length===1?'':'s'} require review.`);
  state.journeys.forEach((x,i)=>{if(!validISODate(x.start)||!validISODate(x.end)||x.end<x.start)issues.push(`Journey ${i+1} dates are invalid.`);});
  issues.push(...vaultIssueList());
  state.reservations.forEach((x,i)=>{if(Math.abs(Number(x.aud||0)-reservationAudValue(x))>.01)issues.push(`Reservation ${i+1} calculation mismatch.`);});
  state.journeys.forEach((x,i)=>{if(Math.abs(Number(x.spend||0)-journeySpendAud(x))>.01)issues.push(`Journey ${i+1} linked spend is out of sync.`);});
  const el=$('#app-check');if(!el)return;
  el.className=issues.length?'warning':'success';el.textContent=issues.length?`ISSUES — ${issues.join(' · ')}`:'APP OK — offline storage, itinerary, dates, budgets and calculations passed.';
  if(!issues.length){state.settings.lastVerified=itineraryReferenceDate();saveState();}
}

