    el.className=failures.length?'warning':'success';
    el.innerHTML=`<b>${failures.length?'WORKFLOW TEST FAILED':'FULL WORKFLOW TEST PASSED'}</b><div class="test-results">${checks.map(x=>`<div><span>${x.pass?'✓':'✕'} ${esc(x.name)}</span>${x.detail?`<small>${esc(x.detail)}</small>`:''}</div>`).join('')}</div>`;
