let activeMapDrag = null;
document.addEventListener('pointerdown', event => {
  const pin = event.target.closest('[data-route-edit],[data-detail-route-edit]');
  if (!mapEditMode || !pin) return;
  const grid = pin.closest('.world-grid');
  if (!grid) return;
  event.preventDefault();
  pin.setPointerCapture?.(event.pointerId);
  activeMapDrag = { pin, grid, id: pin.dataset.routeEdit||pin.dataset.detailRouteEdit, detailId:pin.dataset.detailRoutePoint||'', pointerId: event.pointerId };
  pin.classList.add('dragging');
});
function refreshDraggedRouteLines(pin, grid) {
  const index=Number(pin.dataset.routeIndex);
  if(!Number.isFinite(index))return;
  const pins=[...grid.querySelectorAll('[data-route-index]')].sort((a,b)=>Number(a.dataset.routeIndex)-Number(b.dataset.routeIndex));
  const pointAt=i=>{const node=pins.find(item=>Number(item.dataset.routeIndex)===i);return node?clampMapPoint({x:Number(node.dataset.mapX),y:Number(node.dataset.mapY)}):null;};
  const updateLeg=legIndex=>{
    const a=pointAt(legIndex),b=pointAt(legIndex+1);if(!a||!b)return;
    const parts=mapReadableRouteGeometry(a,b);
    const groups=[...grid.querySelectorAll(`[data-route-leg="${legIndex+1}"]`)];
    groups.forEach((group,partIndex)=>{
      const part=parts[partIndex]||parts[parts.length-1];if(!part)return;
      group.querySelectorAll('path').forEach(path=>path.setAttribute('d',part.d));
      const direction=group.querySelector('.route-direction');if(direction){direction.setAttribute('cx',String(part.mx));direction.setAttribute('cy',String(part.my));}
      const order=group.querySelector('.route-order');if(order){order.setAttribute('x',String(part.mx));order.setAttribute('y',String(part.my-2.1));}
    });
  };
  updateLeg(index-1);updateLeg(index);
}
document.addEventListener('pointermove', event => {
  if (!activeMapDrag || event.pointerId !== activeMapDrag.pointerId) return;
  const { pin, grid } = activeMapDrag;
  const rect = grid.getBoundingClientRect();
  const x = Math.max(3, Math.min(97, ((event.clientX - rect.left) / rect.width) * 100));
  const y = Math.max(4.4, Math.min(94.8, ((event.clientY - rect.top) / rect.height) * 100));
  pin.style.left = `${x}%`;pin.style.top = `${y}%`;
  pin.dataset.mapX = String(Math.round(x * 10) / 10);pin.dataset.mapY = String(Math.round(y * 10) / 10);
  refreshDraggedRouteLines(pin, grid);
});
document.addEventListener('pointerup', event => {
  if (!activeMapDrag || event.pointerId !== activeMapDrag.pointerId) return;
  const { pin, id, detailId } = activeMapDrag;
  const journey = state.journeys.find(item => String(item.id) === String(id));
  if (journey) {
    if(detailId){
      journey.routePoints=normalizeDetailedRoutePoints(journey.routePoints).map(point=>String(point.id)===String(detailId)?{...point,mapX:Number(pin.dataset.mapX),mapY:Number(pin.dataset.mapY)}:point);
      const entry=state.itinerary.find(item=>String(item.id)===String(journey.sourceItineraryId||''));
      if(entry)entry.routePoints=normalizeDetailedRoutePoints(entry.routePoints).map(point=>String(point.id)===String(detailId)?{...point,mapX:Number(pin.dataset.mapX),mapY:Number(pin.dataset.mapY)}:point);
      saveState(entry?'itinerary':'journeys','map-detail-drag');showToast('Detailed route stop moved.');
    }else{
      journey.mapX = Number(pin.dataset.mapX);journey.mapY = Number(pin.dataset.mapY);
      saveState('journeys','map-drag');showToast('Journey point moved.');
    }
  }
  pin.classList.remove('dragging');activeMapDrag = null;render();
});

/* Itinerary planning-map destination + detailed route positioning, saved fully offline */
let activeItineraryMapDrag=null;
document.addEventListener('pointerdown',event=>{
  const pin=event.target.closest('[data-itinerary-map-position],[data-itinerary-route-point-position]');
  if(!itineraryMapPositionMode||!pin)return;
  const grid=pin.closest('.world-grid');if(!grid)return;
  event.preventDefault();event.stopPropagation();
  pin.setPointerCapture?.(event.pointerId);
  activeItineraryMapDrag={pin,grid,id:pin.dataset.itineraryMapPosition||pin.dataset.itineraryRoutePointPosition,detailId:pin.dataset.routePointId||'',pointerId:event.pointerId,moved:false};
  pin.classList.add('dragging');
});
document.addEventListener('pointermove',event=>{
  if(!activeItineraryMapDrag||event.pointerId!==activeItineraryMapDrag.pointerId)return;
  const {pin,grid}=activeItineraryMapDrag,rect=grid.getBoundingClientRect();
  const x=Math.max(3,Math.min(97,((event.clientX-rect.left)/rect.width)*100));
  const y=Math.max(4.4,Math.min(94.8,((event.clientY-rect.top)/rect.height)*100));
  pin.style.left=`${x}%`;pin.style.top=`${y}%`;
  pin.dataset.mapX=String(Math.round(x*10)/10);pin.dataset.mapY=String(Math.round(y*10)/10);
  activeItineraryMapDrag.moved=true;
});
function finishItineraryMapDrag(event){
  if(!activeItineraryMapDrag||event.pointerId!==activeItineraryMapDrag.pointerId)return;
  const {pin,id,detailId,moved}=activeItineraryMapDrag;
  if(moved){
    const entry=state.itinerary.find(item=>String(item.id)===String(id));
    if(entry){
      if(detailId)entry.routePoints=normalizeDetailedRoutePoints(entry.routePoints).map(point=>String(point.id)===String(detailId)?{...point,mapX:Number(pin.dataset.mapX),mapY:Number(pin.dataset.mapY)}:point);
      else{entry.mapX=Number(pin.dataset.mapX);entry.mapY=Number(pin.dataset.mapY);}
      itineraryMapSelectedId=entry.id;saveState('itinerary',detailId?'map-detail-position':'map-position');showToast(detailId?'Detailed route stop positioned and saved offline.':'Itinerary marker positioned and saved offline.');
    }
  }
  pin.classList.remove('dragging');activeItineraryMapDrag=null;render();
}
document.addEventListener('pointerup',finishItineraryMapDrag);
document.addEventListener('pointercancel',finishItineraryMapDrag);
